using System;
using System.Collections.Generic;
using System.Linq;
using UnityEditor;
using UnityEngine;
public static class VerifySkillAssets
{
 public static object Run(){var checks=new List<string>();Action<bool,string> check=(b,s)=>{if(!b)throw new Exception(s);checks.Add(s);};
 var prefab=PrefabUtility.LoadPrefabContents("Assets/Prefabs/Player/PlayerHolder.prefab");try{check(prefab.GetComponentsInChildren<Transform>(true).All(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)==0),"PlayerHolder has no missing scripts");var progress=prefab.GetComponentInChildren<PlayerSkillProgress>(true);var hud=prefab.GetComponentInChildren<SkillFeedbackHUD>(true);check(progress!=null&&progress.curve!=null&&progress.definitions.Length==10,"PlayerHolder has configured runtime owner and definitions");check(hud!=null&&hud.progress==progress&&hud.canvas!=null&&hud.font!=null&&hud.levelUpSound!=null&&!hud.showDebug,"PlayerHolder HUD references, sound and hidden debug are valid");check(prefab.GetComponentInChildren<SkillbookTestSupply>(true)==null,"Production prefab has no test book supply");}finally{PrefabUtility.UnloadPrefabContents(prefab);}
 var books=AssetDatabase.FindAssets("t:Skillbook").Select(g=>AssetDatabase.LoadAssetAtPath<Skillbook>(AssetDatabase.GUIDToAssetPath(g))).ToArray();check(books.Length==10&&books.Select(b=>b.skill).Distinct().Count()==10,"Ten distinct skillbook assets exist");foreach(var book in books)check(book.name=="Skillbook: "+book.skill&&book.MaxStackSize==1&&!book.Stackable&&book.icon!=null,"Valid book asset: "+book.name);
 var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();check(scene.path.EndsWith("/Gameplay_Test.unity"),"Original editing Gameplay_Test remains active");check(scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).All(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)==0),"Gameplay_Test has no missing scripts");var player=UnityEngine.Object.FindFirstObjectByType<PlayerSkillProgress>();check(player!=null&&player.CaptureState().experience.All(x=>x==0),"Saved test player starts with zero XP");check(UnityEngine.Object.FindFirstObjectByType<SkillbookTestSupply>().books.Length==10,"Saved test supply has all ten books");var node=AssetDatabase.LoadAssetAtPath<ResourceNodeDefinition>("Assets/ResourceNodes/CopperDeposit.asset");check(node.awardsSkillXP&&node.xpSkill==RpgSkill.Mining&&node.skillXP==25,"Copper definition awards Mining XP");
 GameplayModernizationValidation.Run();check(true,"Existing full GameplayModernizationValidation completed successfully");var result=new{passed=true,count=checks.Count,checks};System.IO.File.WriteAllText("Assets/Plan/Validation/skills-assets.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;}
}
